import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷二十四","description":"周易經傳集解 - 周易經傳集解卷二十四","frontmatter":{"title":"周易經傳集解卷二十四","description":"周易經傳集解 - 周易經傳集解卷二十四"},"headers":[],"relativePath":"classics/jingchuan-jijie/025.md","filePath":"classics/jingchuan-jijie/025.md"}'),r={name:"classics/jingchuan-jijie/025.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷二十四",tabindex:"-1"},[n("周易經傳集解卷二十四 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷二十四","aria-label":"Permalink to “周易經傳集解卷二十四”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷二十四 ​宋林栗撰序。卦曰：升而不已必困，故受之以困。「困」之為卦，「升」之變也。自「升」之「困」，巽反為「兌」，坤變為坎，上下相宜而成。「巽」為木，「兌」為澤，木藏而澤見，則澤滅之矣。「坤」為地，「坎」為水，地藏而水見，則水漫之矣。是以謂之「困」也。「升」之上六，其彖為「冥升」者，升而不已也。升而不已，其困必矣。受之以困，不亦宜乎？困：亨，貞，大人吉，無咎，有言不信。彖曰：「困」，剛揜也。險以說，困而不失其所，亨，其惟君子乎！「貞大人吉」，以剛中也。「有言不信」，尚口乃窮也。下坎上「兌」，成卦曰「困」者，初為「坎」，二為「離」，三為「巽」，四為「兌」。「坎」為水，離為火，巽為木，「兌」為金。火困於水，水困於金，是以謂之「困」也。所以然者，「坎」在其下，兌在其上，而「離」、巽陷於其中。故曰：離，明也；坎，險也；巽，順也；兌，說也。離、巽為君子，坎、兌為小人。君子見揜於小人，是以謂之「困」也。以爻考之，九二之剛為初六、六三之所揜，九四、九五為六三、上六之所揜，謂之困也，不亦宜乎？故子曰：「困，剛揜也。」剛揜於柔，困之象也。「困，亨，貞大人吉，無咎」，何謂也？曰：坎，險也；「兌」，說也。在險而能說，困不失其所亨也。顏氏之子，一簞食，一瓢飲，在陋巷，人不堪其憂，回也不改其樂，茲其所以為亨歟！「貞」，正也，固也。「困」之六爻，三陰揜剛者也，三陽為柔之所揜也。然三陰雖能揜剛，而皆不得中，據非其位；三陽雖為柔揜，而二五得中，不失其正。夫二、五者，「困」之所謂大人者也。以此為正，以此為困，吉又何咎哉？然而不曰「大人貞吉」，而曰「貞大人吉」，何也？曰：大人者，以剛中為正者也；小人者，以過中為正者也。貞乎大人則吉，貞乎小人則兇，舉此以明彼也。「有言不信」，何謂也？曰：九四、九五皆有「兌」體為口舌，故有言象。當困之時，所有言而不見信，固其宜矣。若尚口而爭之，則喪我而逐物，窮自招也。夫惟君子剛中而守正，居易以俟命，斯為善處困矣。或曰：吾子言兌為小人，而九四、九五體之，何也？曰：易者，易也，變通不窮之謂也。由四象而言之，則以「坎」、「兌」而揜離、巽，是以謂之小人。即六爻而論之，則九四、九五見揜而能說，是以不失為君子也。象曰：「困」，德之辨也。困而不失其亨，君子之所以辨於小人也。又曰：「困窮而通」，即所謂「不失其亨」是也。又曰：「困以寡怨，下學而上達，知我者其天乎？夫何怨之有？」象曰：澤無水，「困」，君子以致命遂志。「澤」者，「兌」也；「水」者，「坎」也。水在澤下，不曰「澤中有水」，而曰「澤無水」，何也？曰：水以流行為功，在澤下，澤不流，無水之象也。所貴乎澤者，貴其說萬物也。水在澤下，足以自潤，而不足以及物，澤道困矣，謂之無水可也。水不及物，豈澤之願哉？致其命之當然，遂其志之所樂，則在困而常亨矣。富貴利達，命也；仁義道德，志也。雜卦曰：「困，相遇也。」「困」之為卦，以剛為柔揜而成。其在六爻，以剛柔相遇為義。何則？君子小人，如水火之不同，如薰蕕之不併，幸而不相遇則已，若使薰蕕同器而藏，水火同釜而爨，則火必見揜於水，薰必見揜於蕕，此困之所以為剛揜也。是故九二與初六相遇者也；九四與六三相遇者也；九五與上六相遇者也，此其所以為「困」也。「困」之諸爻，剛柔相半，非多寡之不齊、強弱之敵也。然其所以為「困」者，初六揜於下，上六揜於上，而三陽陷於其中故也。其所以困而卒為亨者，九二得下卦之中，九五得上卦之中，而三陰皆不當其位故也。然初六心合六三，然後能揜九二；六三心合上六，然後能揜九四、九五。譬如陰柔小人締交合黨以困君子，而其君子能剛中而守正，不失其所亨，則小人自困矣。故卦雖為「困」，其實「亨」也。「困」者，三陽也；「困」之者，三陰也。三陽爻言「困於酒食」、「困於金車」、「困於赤紱」者，言相近而不相得也。小人之困君子，不過困其酒食、車服而已，而君子之道不為之困也。三陰爻言「困於株木」、「困於石」、「困於葛藟」者，言相與而不能相濟也。小人易合而難久，既已困君子矣，及其勢窮力盡，視其黨與無足恃以存者，是以困窮而莫之救也。即其相遇以求之，六爻之義粲然矣。初六：臀困於株木，入於幽谷，三歲不覿。象曰：「入於幽谷」，幽不明也。初六，「坎」也。以陰居剛，而在下卦之下，應乎九四。四，「離」「兌」也。故曰：「臀困於株木，入於幽谷。」初六合六三以困九二者也，有應在四，而反交於三，陰柔不中，不當其位，相與而不能以相濟也。三體「巽」為木，孤立二陽之中，「株木」之象也。初與三皆「坎」，「坎」為谷，「巽」為入，最處坎窞之下，「入於幽谷」之象也。三之不能庇初，猶株木之孑立而不能庇物也。初之不能助三，猶「入於幽谷」而不能出也。是以有「臀困」之象焉。「臀」，體之末，初六是也。自三視之為「臀」也，求全處安而不能進者也。望庇於株木，其困不亦宜乎？「夬」之九四，「姤」之九三，皆指上六。初六為「臀」，此獨指本爻者，易之互文皆如此也。說者或謂六三為「臀」，則失之矣。故曰：「三歲不覿」。自初至四，所歷三爻，初為「坎」，四為「離」。「離」性炎上，「坎」性趨下。「離」，明也；「坎」，幽也。初六有應在四，而乃「入於幽谷」，至於三歲而不覿其配焉，兇可知矣。故子曰：「入於幽谷，幽不明也。」言初六之不明，故至於此也。王弼曰：「幽者，不明之辭。」九二：困於酒食，朱紱方來，利用亨祀。徵兇，無咎。象曰：「困於酒食」，中有慶也。九二，「離」也。以陽居柔而在下卦之中，上無其應，而介於初六、六三之間，二爻皆「坎」，而三又「巽」也，故曰：「困於酒食，朱紱方來。」「坎」為酒，「離」為食，相近而不相得，故有「困於酒食」之象。「離」，南方之卦，其色赤，二與四皆「離」，故有「朱紱方來」之象，故曰「利用享祀」。夫酒食者，享祀之所須也；朱紱者，享祀之所服也。雖無酒食之豐，而不失朱紱之服，以之享祀，何所不可？夫豈以酒食之困而易其志哉？此君子之所以亨也，故曰：「徵兇，無咎。」向若「困於酒食」，遂往而求之，「兇」固宜矣，又誰咎乎？而子曰「困於酒食，中有慶」者，言二雖困而不失其中，故有「朱紱」之「慶」也。二言「有慶」，五言「有說」，即彖之所謂「險以說」，系所謂「窮而通」者也。六三：困於石，據於蒺莉，入於其宮，不見其妻，兇。象曰：「據於蒺莉」，乘剛也。「入於其宮，不見其妻」，不祥也。六三下體為「坎」，下體為「巽」，以陰居剛而在下卦之上，上無其應，而介於九二、九四之間，二爻皆「離」，而四又「兌」也，故曰：「困於石，據於蒺䔧，入於其宮，不見其妻。」六三合初六以困九二，合上六以困九四、九五者也。然皆陰柔不中，不當其位，相與而不能相濟。初「入於幽谷」，故有「困於石」之象。二剛而在下，故有「據於蒺䔧」之象。初之不足恃，猶石之頑然而不能生物也。二之不可揜，猶「蒺䔧」之堅而不可據也。木之遇石，木之困也；「據於蒺䔧」，其傷必矣。上六則其所位宮也，三非陽也，自以為陽，陽而求配於上六，上六非其配也，是入於其宮而不見其妻也。三既不得志於二，又不得志於初，反入其宮，不見其配，兇可知矣，故曰「兇」。子曰：「據於蒺䔧」，乘剛也；「入於其宮，不見其妻」，不祥也。又曰：非所困而困焉，名必辱；非所據而據焉，身必危。既辱且危，死期將至，妻其可得見耶？言六三不知初之無能為，而挾之以取困，其召辱矣；不知二之不可乘，而揜之以速禍，其身危矣。故初之「不覿其配」，三之「不見其妻」，皆謂小人不安其分，而不行險以徼倖。既失所圖，則顛沛失措，無投足之地。此聖人深見小人之情狀，而告戒之如此之明也。九四：來徐徐，困於金車，吝，有終。象曰：「來徐徐」，志在下也；雖不當位，有與也。九四下體為「離」，上體為「兌」，以陽居柔，而在上卦之下，應乎初六，而乘乎六三，二爻皆「坎」，而三又「巽」也，故曰「來徐徐，困於金車」。四之見揜於二陰，與二五同患者也。然四不中，不當其位，故下應於初而比於三。初既「入於幽谷」，不能自出，三又「困於石」，「據於蒺䔧」，四乃徐徐其來，以從五焉。「兌」為金，「坎」為車，相近而不相得，故有「困於金車」之象。夫金者，祭祀之所陳也；車者，祭祀之所乘也。祭而無金與車，宜不可以祭矣。然苟有明信，則筐筥錡釜可以薦於神；義弗當乘，則舍車而徒，所以賁其趾。夫豈以金車之困而易其志哉？此君子之所以亨也，故曰：「吝有終」。當困之時，君子為小人所困者也。四不能亟從君子之朋，而徐徐以待小人之配，其為可羞吝，宜矣。然以其承於九五，五為之與，是以幸而有終也。故子曰：「來徐徐，志在下也；雖不當位，有與也。」九五：劓刖，困於赤紱。乃徐有說，利用祭祀。象曰：「劓刖」，志未得也；「乃徐有說」，以中直也；「利用祭祀」，受福也。九五，「兌」也，以陽居剛而在上卦之中，下無其應，而承於上六，連於六三，二爻皆「巽」，而三又「坎」也，故曰「劓刖」。「困於赤紱」，「劓」，刑其上也；「刖」，刑其下也。「兌」為毀折，故有「劓刖」之象。九四雖與五比，而下應於初，是以九五上見「劓」於上六，下見「刖」於六三。夫二五皆見揜，其為「劓刖」則同也。不言於二而言於五者，明其不獲四之助也。二「離」而五「兌」也。二四皆以陽居柔，獨五以陽居剛，則其見揜，有甚於二四者矣，是以系之「劓刖」也。「離」為「赤紱」，二四皆「離」，而五獨體「兌」，相近而不相得，故有「困於赤紱」之象。在二謂之「朱」，在五謂「赤」，古之制服，蓋有其別矣。鄭康成雲：「黻，其色皆赤，尊卑以深淺為異。天子純朱，諸侯黃朱，大夫赤而已。」蓋互而言之與？赤紱者，祭之所服也。祭而無服，宜不可以祭矣。然禮有弗獲，雖降服以祭可也。夫豈以赤紱之困而易其志哉？此君子之所以亨也。故曰「乃徐有說，利用祭祀」。孟子有言：「不得，不可以為說；無財，不可以為說。」五體兌為說，九四不獲於初，然後反而從五，故徐有喜說之道焉。夫君子之所重，莫重於祭。酒食，祭之所須也；金車，祭之所用也；赤紱，祭之所服也。小人之肆志也，初困其酒食，中困其金車，終困其赤紱，而君子恬然不以動其心，則其所以自處者，可謂綽綽然有餘裕矣。彼小人者，其能卒困之耶？故子曰：「劓刖，志未得也。乃徐有說，以中直也；利用祭祀，受福也。」夫酒醴、牲牢、金車、赤紱，固所以事神之具，然君子剛中守道，不為利害得喪易其本心，乃鬼神之所福也。其曰祀、曰亨、曰祭者，以言祀天神，祭地祗，享人鬼，無所不可，蓋互言其文也。或難愚曰：「孟子有言，犧牲不成，粢盛不潔，衣服不備，則不敢以祭。唯士無田，則亦不祭。而此言困於酒食、金車、赤紱皆可以祭，何也？」應之曰：孟子固言仕如此其急也。又曰：古之人未嘗不欲仕，又惡不由其道。然而孟子以謂士無田則不祭，三月無君則吊。若是，則不由其道而得之者，吾恐孟子有時而從之也。且孟子既不肯枉道以事人，不獲犧牲粢盛以共祭祀，然則獨不祭其先乎？聖人則有「菜羔瓜祭」之語，「尊酒簋貳」之文，烏有所不祭哉？傳曰：「澗溪沼沚之毛，蘋蘩薀藻之菜，筐筥錡釜之器，潢汙行潦之水，可以薦之鬼神。」此語蓋本於詩之召南，吾不敢以孟子之說而易聖人之經也。上六：困於葛藟，於臲卼，曰動悔有悔，徵吉。象曰：「困於葛藟」，未當也；「動悔有悔」，吉行也。上六，「巽」也。以陰居柔，而在上卦之上，下無其應，而乘於九五之兌，故曰：「困於葛藟，於臲卼。」上六合六三以困二陽者也。三體巽，巽為蕃鮮而合於上六，故葛藟之象。五體兌，兌為剛滷而在己之下也，故有臲卼之象。三之不可恃，猶葛藟之不能自立也。五之不可揜，猶臲卼之難乘也。按文當曰「困於葛藟，據於臲卼。」脫一「據」字。三與上皆巽，「巽」為木，然自初視三，則初為石，而三為株木。自上視三，則上為水，而三為藟葛。木之有葛藟，木之困也。東坡曰：「以柔用剛，則乘之者至以為蒺䔧；以剛用剛，則乘之者以為臲卼而已。」據於臲卼，益不可也。故曰「動悔有悔，徵吉」者，為上六謀之之辭也。謂動之有悔，然而不動，未嘗無悔也，盍改圖乎？徵，猶行也，惟速去之，乃為吉矣。他爻揜剛者，皆有兇象，惟上六居卦之窮，窮則能變，下無其應，行莫之系，是以免於兇，而獲徵吉之辭也。故子曰：「困於葛藟，未當也。」以陰居柔，疑若當位矣。然一卦之上，豈陰柔之所宜居？亦為未當也。需之上六亦曰「不當位」，與此同義。動悔有悔，吉行也。吉字，當讀為句絕。言既曰「悔」，而又云「吉」者，以其能行故爾。缺。序卦曰：「困乎上者必反下，故受之以井。」井之成卦，困之反也。自困之井，坎反居上，兌反為巽，上下相易而成也。坎為水，兌為澤，巽為木。水在澤下，不足以及物，是以謂之困。水在木上，則有及物之功矣。取諸井象，不亦宜乎？所以然者，兌已上窮，其勢必反下，是以復入於坎，而成井象也。或曰：離兌反巽，而剛揜之象自若也，烏在其不為困乎？曰：困之諸陰，皆不當位，而於九五無相無之情，是以揜之而為困也。井自九三以上，皆有離下坎上既濟之象，謂之剛揜，不已疏乎？故雜卦曰：「井通而困相遇也。」井：改邑不改井，無喪無得，往來井井。汔至，亦未繘井，羸其缶，兇。彖曰：巽乎水而上水，井。井，養而不窮也。「改邑不改井」，乃以剛中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以兇也。下巽上坎成卦曰「井」者，初為巽，二為兌，三為離，四為坎。巽，入也；坎，陷也。入而陷焉，溺人之象也，為其有兌、離之象焉。兌，說也。離，麗也。說而有所麗，是以謂之井也。巽，木也。坎，水也。木入乎水，滅水之象也，為其有兌、離之象焉。兌上缺也，離中虛也，此木之所以受水也。兌上行也，離炎上也，此木之所以上水也，是以謂之井矣。故子曰：巽乎水而上水，井。井養而不窮也。範諤昌曰：「巽乎水當作巽乎木。」愚謂不然。巽自是木矣，豈得雲「巽於木」乎？巽，入也。木入乎水，而水在木上，斯以為井之象矣。井：「改邑不改井，無喪無得，往來井井。」何謂也？曰：井者，困之反也。困反為井，而二、五不變，是改邑不改井之象也。井也者，君子之德也。邑也者，眾人之居也。邑可改而井不可改者，以其剛中也。剛中也者，泉在其中也。改邑而亦改之，則非是井矣。人之見是美井，遷而就之，至於成邑，則有之矣。未有井憂不食，遷而就邑也。是故政教有時而汙隆，風俗有時而美惡，而君子之道，終始如一，曾不少變，然後可以比德於井矣。井之為德，旱而不竭，潦而不盈，人之我取，於我何得？人不我取，於我何喪？取者日來，去者日往，或往或來，而為井者常自若也，故曰：「往來井井。」若貪得而患喪，惡往而好來，則隨物而遷徙矣。「汔至，亦未繘井，羸其瓶，兇。」何謂也？曰：汔，幾也。繘，綆也。瓶，汲器也。羸，敗也。巽為繩，故有繘井之象。離為大腹，兌為毀折，故有羸其瓶之象焉。幾至而未至者，其綆短也。綆短而不及泉，與未嘗有綆同也。瓶既敗矣，雖有綆，安施乎？故子曰：「汔至，亦未繘井」，未有功也。「羸其瓶」，是以兇也。綆短而不及泉，是求之未至，汲之未深，賢人之不為我用，致誠而盡禮焉可也，未可以望其功也。「羸其瓶」，是無以受之者也。內惑於聲色，外蔽於謟諛，諫則不行，言則不聽，士將望望而去之，雖得之，亦必失之，此其所以兇也。傳曰：「得士者昌，失士者亡。」謂之兇也，不亦宜乎！象曰：木上有水，井，君子以勞民勸相。水者，「坎」也；木者，「巽」也。木上有水，井之象也。或曰：「古者汲用瓶、甕，木上有水，何義也？」曰：木上有水，轆轤、桔槔之象也。然謂古者汲用瓶、甕，本無所據，亦陋者之言爾。彼以彖言「羸其瓶」，爻言「甕敝漏」，故有是說，不知爻、彖之辭，因羸敝而言瓶、甕耳。耒耜、舟楫、弧矢、杵臼之利，皆聖人作，蓋中智之所不及也。若夫汲用瓶、甕，可以施於尋丈之間，過此以往，至於九仞而後及泉者，非復瓶、甕之所能；汲用木器，不待智者而後知之也，況天地自然之象，已寓於制器之前乎！「君子以勞民勸相」，何謂也？「木上有水」，勞而後得之者也。苟有以與之，雖盛暑沾汗，祁寒凍膚，而抱甕出灌者，不以為勞。苟無以與之，則棄而莫之顧矣。井之為德，取之而不竭，用之而不窮者也。隨其力之多寡，而各得其所欲者也。是以汲者四面而至焉。君子之所以勞民勸相，亦如是而已。向使終歲勤動，不得以養其父母，育其妻子，雖重賞以勸之，嚴刑以驅之，而民弗從矣。雜卦曰：「井通而困，相遇也。」不相遇則不能相困，故困以相遇為義。泉之在地，其脈流通，故井以通為義。困以三陽為君子，三陰為小人，陽剛而陰柔，陽貴而陰賤也。井以三陽為泉，三陰為井，陽實而陰虛，陽動而陰靜也。是故井之諸爻，義皆相通，而以中正上下為吉凶之決，何也？正且潔者，井之正也；清且寒者，泉之正也。何謂中？邑居之會也。何謂上？汲引而出之也。何謂下？流濁之所鍾也。初六在下曰「泥」，六四在中曰「甃」，上六在上曰「收」、曰「幕」，此言井也。九二不正則無與，九三不中則不食，九五中正則井洌泉寒，而人食之矣，此言泉也。井之為通，其是之謂歟？故系曰：井，德之地也。居潔則清，處穢則濁，所以德為之地也。又曰：「井居其所而遷」，即所謂「改邑不改井」，往來井井者也。又曰：井以辨義，泥之所不能侵，鮒之所不能射，敝漏之甕所不能汲，君子之所以辨義，如斯而已。初六：井泥不食，舊井無禽。象曰：「井泥不食」，下也。「舊井無禽」，時舍也。初六，「巽」也，以陰居剛而在下卦之下，上無其應，而承於九二之兌，故曰：「井泥不食，舊井無禽。」夫泉出於地中，而井施於泉上。初六之陰有井之象矣，而下無陽爻，是有井而無泉也。處於最下，不中不正，則泥塗濁穢之所歸也。「兌」為澤，「巽」為入，故有「井泥」之象。「兌」為口，而與「巽」不相得，故有「不食」之象。「舊井」者，泥之甚也；「無禽」者，不食之甚也。夫以初六之「無泉」，宜若不為井矣，為其居於剛者，是以猶有「井泥」之象焉，是泉與泥相混者也。井之有「泥」，人之所棄，禽之所食也。「舊井無禽」，則泥深而泉竭矣；有井而「無泉」，禽亦棄之也。子貢曰：「君子惡居下流，天下之惡皆歸焉。」初六之謂矣。故曰：「井泥不食，下也；舊井無禽，時舍也。」此與「乾」初九、九二之象，文同而旨異矣。初六以不中不正而居於下流，其始見棄於人，其終見棄於禽。然則君子之所養與其所居者，可不謹哉？唐八司皆一時名士也，如柳宗元、劉禹錫，猶欲自振於濁之中，所謂「井泥不食」者也。至若韋、陸之徒，則人禽皆舍之矣。九二：井谷射鮒，甕敝漏。象曰：「井谷射鮒」，無與也。九二，「兌」也，以陽居柔而在下卦之中，上無其應，而乘於初六之「巽」，故曰「井谷」。「井谷」，「坎」井也。「兌」為澤，「巽」為入，故有「井谷」之象。井之道上行，泉在下而井在上。九二剛中，有泉之象矣。而上無陰爻，是有泉而無井也。為其居於陰而乘乎「巽」，是以有「井谷」之象焉。水之所鍾而為谷，人之所以汲為井也。所以然者，不正而中故也。水之所鍾而為谷，非泉之正也。人之所汲以為井，得邑居之中也。故曰「射鮒，甕敝漏」。「鮒」，小魚也，或曰蝦蟆也。甕，汲器也。「巽」為入，為魚，故有「射鮒」之象。「兌」為口，為毀折，故有「甕敝漏」之象。泉居深井之中，非汲則莫能致汲而用漏甕，未有能上之者也。惟坎井之泉，則雖用漏甕，而可以挹取之矣。孔子曰：「清斯濯纓，濁斯濯足矣。」自取之也。然則九二之不正，而得鮒與敝之漏甕，宜矣。夫泉者，君子之所受於天者也；而井者，君子之所修於身者也。有泉而無井，是自棄也；有井而無泉，則亡之矣。故子曰：「井谷射鮒，無與也。」言其上無陰爻，莫與井之，是以鮒得而射之也。或曰：吾子以不正為二之咎，而夫子言其「無與」，則豈二之咎乎？曰：惟其不正，是以無與。使九居初而六居二，是正而有與也。泉苟寒而在邑之中，則井斯潔矣，豈有以之坎谷而反棄之也歟？九三：井渫不食，為我心惻，可用汲，王明，並受其福。象曰：「井渫不食」，行惻也。求「王明」，受福也。九三上體為離，下體為兌，以陽居剛而在下卦之上，應乎上六而承於六四，二爻皆坎，而四又巽也，故曰：「井渫不食，為我心惻。」兌為澤，離為明，故有「井渫」之象。離為食，巽為不果，故有「不食」之象。坎為憂傷，為心病，故有「心惻」之象。渫，清也。清者，泉之正也。九三正而有與，是泉清而井潔矣。然而不食者，非邑之中矣。我，三自謂也。行道之人見井渫而不食，則為之惻然，是為我之故而惻其心也。夫以三四離坎相配，而有不食之象者，巽兌為之間也。三自以應在上，雖與四比而不相得，是以惻之而已矣。夫既惻之，則曷為不食之歟？曰：是井也，可用汲而得之也，非若九二之谷，可挹而取之也。汲者非瓶與繘則莫能致，瓶與繘非行道之所有也，是以心惻而不得食也，故曰「可用汲」。可用汲者誰與？其邑居之人也。瓶與繘，居者之所有也，居者汲之，則行者亦沾其賜矣。故行者樂以告居者曰：是井之渫也，非汲則莫能致也。苟從吾言，吾與子皆得而食之矣。故曰「王明，並受其福」。以九居五，其體為離，故有「王明」之象。民之見賢而不用，賢者又不求人之知，則欲以告其王，庶幾吾王之明，汲而用之，則民與王並受其福，其心豈不然也？故子曰：「井渫不食，行惻也。求王明，受福也。」行惻者，行人之惻，而非井之惻也。求王明者，人之求之，而非井之求之也。明者，知渫之可食，而賢之可用也，此所以受福也。司馬遷乃曰：「王之不明，豈足福哉？」是何言也！王安石乃曰：「君子之於君也，以不求求之，異乎人之求之也。」惡！是何言也！君子之不求也，豈以為要君之術也哉？或曰：「蒙之象曰：山下出泉，蒙。謂坎為泉也。今吾子以澤為泉，毋乃非歟？」曰：「澤，止水也；坎，流水也。山下出泉，謂流水也，故坎取之。今井渫不食，止水也，而兌取之，不亦宜乎哉？若夫九五之泉，上下皆坎，則取諸左右逢其原，且北方之氣，是以謂之寒泉也。」曰：「然則九二之兌，謂之井谷，何也？」曰：「水之所鍾而為谷，亦止水之象也。」曰：「九二之井，注而為谷也；九三之井，渫而為清也，吾子皆以為止水。九五之井，洌而泉寒也，吾子乃謂之流水，何哉？」曰：「九二、九三之水，兌也。兌出於本爻，則其止可知矣。九五之水，坎也。坎」在其上，又在其下，則謂之「流水」，宜哉！六四：井甃，無咎。象曰：「井甃無咎」，修井也。六四上體為「坎」，下體為「巽」，以陰居柔而在上卦之下，下無其應，而乘於九三。二，「離兌」也，故曰：「井甃，無咎。」三與四皆正，是井潔而泉清矣。然而不食者，非邑之中也，治其「井甃」，使之「無咎」而已矣。「坎」為水，為勞；「巽」為工，為潔，故有「井甃」之象。井雖渫而不食，久而弗修，亦為廢井矣。惟不忘於甃甓，隨其罅漏而修治之，則泥之所不能混，鮒之所不能射，是以為「無咎」也。顏淵曰：「夫道之不修，是吾醜也。」夫道既已大修而不用，是有國者之醜也。井之自修如此，然而不食，則非井之咎也。故子曰：「井甃無咎，修井也。」井雖不食，而不忘於甃，然後為井也。君子雖不見用，而不忘於自修，然後為君子也。九五：井冽，寒泉，食。象曰：「寒泉」之「食」，以中正也。九五，「離」也，以陽居剛而在上卦之中，下無其應，而介於六四、上六之間，二爻皆「坎」，而四又「巽」也，故曰：「井洌，寒泉，食。」「洌」，潔也。「巽」為潔，故有「井洌」之象。「離」為食，為大腹，故有「食」之象。「洌」者，井之正也。「寒」者，泉之正也。「食」者，邑之中也。安有井洌泉寒，在都邑之中而不見食者乎？故子曰：寒泉之食，以中正也。或曰：吾子以陽為泉，陰為井，今謂坎為寒泉，則六四當之矣。而又系之九五，何哉？曰：此雜卦之所謂通也。泉之在地，其脈流通，故說卦坎為通。今九五之泉，在六四、上六重坎之際，則是左右逢其原也。泉寒井洌，不亦宜乎？或曰：坎為水，離為火，坎為冬，離為夏。若六四之坎為寒泉，至於九五之離，則當為溫泉矣。曰：此則五之所謂食也，其烹而食之義乎？雖烹而食之，猶謂之寒泉也。九五則三之所謂王明者與！上六，井收勿幕，有孚，元吉，大成也。上六，坎也。以陰居柔，而在上卦之上，應乎九三，而乘於九五，二爻皆離，而三又兌也，故曰「井收勿幕」。冪，覆也。本或作冪，非也。收，轆轤也。舊說為綆，非也。坎為輪，故有收象。又為隱伏，故有冪象。井道上行，在一卦之上，井之大成矣。收與冪皆在井上，欲其置收而患其施冪也。收則一取而有餘，不冪則眾汲而無窮。所以然者，以其遠應九三，近乘九五，泉源之富，足以養而不窮故也。故曰「有孚，元吉」。坎為有孚，離下坎上，既濟之象，是以謂之「元吉」也。故子曰：「元吉在上，大成也。」其言「元吉」之辭，不於五而於上者，井雖見食，有冪而無收，則所施不廣，未得為「元吉」矣。夫以孔子用於一邑而一邑治，用於一國而一國治，可謂「井洌寒泉食」矣。然而不得施之於天下，而止於國邑，豈得為「元吉」也哉！周易經傳集解卷二十四，",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
